describe('Notification Click Navigation', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should navigate to related content when clicking a notification', () => {
    // Verify notification is visible
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'New article published');

    // Click the notification
    cy.get('[data-testid="notification-item"]').click();

    // Verify navigation occurred
    cy.url().should('include', '/article');

    // Verify we are on the correct page
    cy.get('[data-testid="article-title"]').should('be.visible');
    cy.get('[data-testid="article-title"]').should('contain', 'New Article');

    // Verify related content is displayed
    cy.get('[data-testid="article-content"]').should('be.visible');
    cy.get('[data-testid="article-content"]').should('contain', 'This is the article content');

    // Verify navigation back button is present
    cy.get('[data-testid="back-to-notifications-btn"]').should('be.visible');
  });

  it('should handle edge case when notification is already open', () => {
    // Open a notification
    cy.get('[data-testid="notification-item"]').click();

    // Verify navigation occurred
    cy.url().should('include', '/article');
    cy.get('[data-testid="article-title"]').should('be.visible');

    // Click the notification again
    cy.get('[data-testid="notification-item"]').click();

    // Verify navigation does not occur again
    cy.url().should('include', '/article');

    // Verify notification is still open
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // Verify related content is still displayed
    cy.get('[data-testid="article-content"]').should('be.visible');

    // Verify back button is still present
    cy.get('[data-testid="back-to-notifications-btn"]').should('be.visible');
  });
});
